// TH16 v1.00a Stage 6 midstage wave: MainSub02 (st06.ecl.txt:712-729) with
// GirlD01 (404-441) and GirlD01_at (443-492).
// Source frame 0 = first enmCreate; card frame 0 = phase_begin, first spawn after OPENING_BUFFER.

const TIME_LIMIT: int = 2320;
const OPENING_BUFFER: int = 120;

// GirlD01_at EX record 0x200000 (VELTIME): a=60, r=0.5/1.0/1.5/2.0, s=keep-angle.
// Scalar speed ramps linearly 1.0 -> 1.0+60*accel along the unchanged bullet angle.
xformdef SHARD_ACCEL(accel: fx) {
    set_accel(accel);
    wait(60);
    set_accel(0fx);
}

// GirlD01_at: etAim 3 fixed ring, count 13/27/30/30, etAngle base = one %RANDRAD per volley,
// speed 1.0, difficulty wait 40/20/15/10, diffI count 15/20/30/40 volleys.
async sub girl_fire() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 13;
    var volleys: int = 15;
    var gap: int = 40;
    var accel: fx = -0.5fx / 60fx;
    if rank == RANK_NORMAL { ways = 27; volleys = 20; gap = 20; accel = 0fx; }
    if rank == RANK_HARD { ways = 30; volleys = 30; gap = 15; accel = 0.5fx / 60fx; }
    if rank >= RANK_LUNATIC { ways = 30; volleys = 40; gap = 10; accel = 1fx / 60fx; }
    wait(60);                                   // GirlD01_at opening wait
    sh_reset(0);
    sh_sprite(0, TH16_SHARD, 4);                // etSprite(0, 10, 4)
    sh_ring(0, 1);
    sh_aim(0, 0);                               // etAim(0, 3): fixed-direction ring
    sh_count(0, ways, 1);
    sh_speed(0, 1fx, 0fx);                      // etSpeed(0, 1.0, 0.2), single layer -> 1.0
    sh_dist(0, -4fx);                           // ANIM a=1 at spawn: position -= 4*velocity
    sh_xform(0, SHARD_ACCEL(accel));
    for i in 0..volleys {
        sh_angle(0, (rand(65536) - 32768) as angle, 0deg); // etAngle(0, %RANDRAD, 0.0)
        sh_fire(0);                             // etOn(0)
        wait(gap);
    }
}

// GirlD01: spawn animation (anm*, wait 60, flag 15 window) omitted per policy; the
// remaining waits keep their order, so the whole body runs 60 source frames earlier.
async sub girl(dir: angle) {
    set_invuln(65535);
    set_hitbox(12fx);                           // setHitbox(24,24): 0.5*24
    set_hurtbox(16fx);                          // setHurtbox(32,32): 0.5*32
    move_vel(0, dir, 0fx, EASE_LINEAR);         // moveVel(%F2, 0.0)
    spawn girl_fire();                          // @GirlD01_at() async
    wait(30);
    move_vel(0, dir, 0fx, EASE_LINEAR);         // moveVel(%F2, 0.0)
    move_speed(60, 0.32fx, EASE_QUAD_IN);       // moveSpeedTime(60, 1, 0.32)
    wait(400);
    move_speed(60, 0fx, EASE_QUAD_IN);          // moveSpeedTime(60, 1, 0.0)
    loop { wait(1000); }                        // GirlD01_784/804: idle until cleared
}

// MainSub02: five GirlD01 at (0,224) on the stage origin, 380 frames apart,
// %F2 = -90/-135/-45/180/0 degrees.
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 224fx, 5000, 0, 0, 0, girl(270deg));
    wait(380);
    _ = spawn_enemy(0fx, 224fx, 5000, 0, 0, 0, girl(225deg));
    wait(380);
    _ = spawn_enemy(0fx, 224fx, 5000, 0, 0, 0, girl(315deg));
    wait(380);
    _ = spawn_enemy(0fx, 224fx, 5000, 0, 0, 0, girl(180deg));
    wait(380);
    _ = spawn_enemy(0fx, 224fx, 5000, 0, 0, 0, girl(0deg));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
